        lines = [l.strip() for l in page.split('\n') if l.strip()]
        if any('Limitations' in l for l in lines[:5]):
            print(f'Limitations found on page {i}')
    if 'Ethical Considerations' in page:
        lines = [l.strip() for l in page.split('\n') if l.strip()]
        if any('Ethical Considerations' in l for l in lines[:10]):
            print(f'Ethical Considerations found on page {i}')
    if 'Use of AI Assistance' in page:
        print(f'Use of AI Assistance found on page {i}')
